import { IEvent } from '../event-interface';
import { ListenerNode } from '../listener-node';
import { IStateData } from '../state-data';
import { AbstractState } from './abstract-state';
import { DispatchingState } from './dispatching-state';

export class NonDispatchingState extends AbstractState {
    private cachedDispatchingState: DispatchingState;

    constructor(parent: IEvent, stateData: IStateData) {
        super(parent, stateData);
        this.cachedDispatchingState = new DispatchingState(this.parent, this.stateData);
    }

    public removeListenerNode(listenerNode: ListenerNode): void {
        super.removeListenerNode(listenerNode);
        this.stateData.listenerNodePool.addNodeToPool(listenerNode);
    }

    public addListenerNode(listenerNode: ListenerNode): void {
        if (this.stateData.tail) {
            listenerNode.previous = this.stateData.tail;
            this.stateData.tail.next = listenerNode;
            this.stateData.tail = listenerNode;
        } else {
            this.stateData.tail = listenerNode;
            this.stateData.head = listenerNode;
        }
    }

    public dispatchEvent(...args: any[]): void {
        this.startDispatching();
        super.dispatchEvent.apply(this, args);
        this.endDispatching();
    }

    private startDispatching(): void {
        this.parent.state = this.cachedDispatchingState;
    }

    private endDispatching(): void {
        this.stateData.listenerNodePool.returnNodesToPool();
        this.addQueueToList();
        this.parent.state = this;
    }

    private addQueueToList(): void {
        let currentQueuedListener: ListenerNode | undefined = this.stateData.queueTail;

        while (currentQueuedListener) {
            this.stateData.queueTail = this.stateData.queueTail!.previous;
            this.addListenerNode(currentQueuedListener);
            currentQueuedListener = this.stateData.queueTail;
        }
    }
}
